import * as os from 'mbjs:os';
import { cwd, dirname, join, resolvePath, resolvePackage, resolveNativePath,
         fileExists, readText } from '../mochinode/index.js';
import { exec } from '../mochinode/lib/process.js';

const DEFAULT_COMPILER = 'E:/sevm/build_ex/tools/mbjsc-sevm.exe';
const FALLBACK_COMPILER = 'E:/bcf/mochiberry/build_manual/mbjsc.exe';
const DEFAULT_ENGINE_ROOT = 'E:/bcf/mochiberry';
const DEFAULT_WORK_DIR = 'E:/sevm/build_ex/.mochijsnative';
const DEFAULT_GCC = 'C:/Users/Administrator/AppData/Local/Microsoft/WinGet/Packages/BrechtSanders.WinLibs.MCF.UCRT_Microsoft.Winget.Source_8wekyb3d8bbwe/mingw64/bin/gcc.exe';
const DEFAULT_STRIP = 'C:/Users/Administrator/AppData/Local/Microsoft/WinGet/Packages/BrechtSanders.WinLibs.MCF.UCRT_Microsoft.Winget.Source_8wekyb3d8bbwe/mingw64/bin/strip.exe';
const NATIVE_EXT = /\.(dll|so|dylib|lbrct|exe)$/i;
const JS_EXT = /\.(js|mjs|cjs)$/i;
const ASSET_EXT = /\.(html?|css|js|mjs|json|png|jpe?g|gif|svg|webp|ico|bmp|mp3|mp4|webm|ogg|wav|flac|pdf|txt|md|csv|woff2?|ttf|otf|eot|map|wasm)$/i;
const ASSET_DIRS = ['public', 'assets', 'static', 'views', 'www', 'dist'];

function q(value) {
    return '"' + String(value).replace(/\\/g, '/').replace(/"/g, '\\"') + '"';
}

function norm(value) {
    const s = String(value).replace(/\\/g, '/');
    const drive = /^([A-Za-z]:)\//.exec(s);
    const absolute = !!drive || s.startsWith('/');
    const prefix = drive ? drive[1] + '/' : absolute ? '/' : '';
    const rest = drive ? s.slice(3) : absolute ? s.slice(1) : s;
    const parts = [];
    for (const part of rest.split('/')) {
        if (!part || part === '.') continue;
        if (part === '..') {
            if (parts.length && parts[parts.length - 1] !== '..') parts.pop();
            else if (!absolute) parts.push('..');
        } else parts.push(part);
    }
    return prefix + parts.join('/');
}

function resolveCompiler(explicit) {
    if (explicit) return explicit;
    try {
        exec('if exist ' + q(DEFAULT_COMPILER) + ' exit /b 0 else exit /b 1');
        return DEFAULT_COMPILER;
    } catch (e) {
        return FALLBACK_COMPILER;
    }
}

function openWriter(path) {
    const fd = os.open(String(path), os.O_WRONLY | os.O_CREAT | os.O_TRUNC);
    if (fd < 0) throw new Error('mochijsnative.build: cannot write ' + path);
    return {
        write(text) {
            const bytes = new TextEncoder().encode(String(text));
            let offset = 0;
            while (offset < bytes.length) {
                const n = os.write(fd, bytes.buffer, offset, Math.min(65536, bytes.length - offset));
                if (!n || n < 0) break;
                offset += n;
            }
        },
        close() { os.close(fd); }
    };
}

function writeText(path, text) {
    const writer = openWriter(path);
    try {
        writer.write(text);
    } finally {
        writer.close();
    }
}

function readBytes(path) {
    const st = os.stat(String(path))[0];
    if (!st) throw new Error('mochijsnative.build: cannot stat ' + path);
    const size = Number(st.size || 0);
    const fd = os.open(String(path), os.O_RDONLY);
    if (fd < 0) throw new Error('mochijsnative.build: cannot open ' + path);
    const out = new Uint8Array(size);
    let offset = 0;
    while (offset < size) {
        const n = os.read(fd, out.buffer, offset, Math.min(65536, size - offset));
        if (!n || n < 0) break;
        offset += n;
    }
    os.close(fd);
    return out.subarray(0, offset);
}

function listFiles(path, out = []) {
    const listed = os.readdir(String(path));
    const entries = Array.isArray(listed) ? listed[0] : [];
    if (!entries) return out;
    for (const entry of entries) {
        if (entry === '.' || entry === '..') continue;
        const child = join(path, entry);
        const st = os.stat(child)[0];
        if (!st) continue;
        if ((Number(st.mode) & os.S_IFDIR) === os.S_IFDIR) listFiles(child, out);
        else out.push(child);
    }
    return out;
}

function findPackageRoot(path) {
    let dir = dirname(path);
    while (dir && dir !== '/' && !/^[A-Za-z]:$/.test(dir)) {
        if (fileExists(join(dir, 'package.json'))) return dir;
        const parent = dirname(dir);
        if (parent === dir) break;
        dir = parent;
    }
    return null;
}

function specifiers(source) {
    const out = [];
    const code = String(source)
        .replace(/\/\*[\s\S]*?\*\//g, ' ')
        .replace(/(^|[^:])\/\/[^\n]*/g, '$1 ');
    const rules = [
        /(?:import|export)\s+(?:[^'";]*?\s+from\s+)?['"]([^'"]+)['"]/g,
        /\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g,
        /\b(?:require|mrequire)\s*\(\s*['"]([^'"]+)['"]/g,
        /\b(?:loadNative|resolveNativePath)\s*\(\s*['"]([^'"]+)['"]/g
    ];
    for (const re of rules) {
        let match;
        while ((match = re.exec(code))) {
            if (out.indexOf(match[1]) < 0) out.push(match[1]);
        }
    }
    return out;
}

function resolveSpecifier(spec, importer) {
    const s = String(spec);
    if (s.startsWith('mbjs:') || s.startsWith('data:') || s.startsWith('node:')) return null;
    if (NATIVE_EXT.test(s)) return resolveNativePath(s, dirname(importer));
    if (s.startsWith('.') || s.startsWith('/') || /^[A-Za-z]:[\\/]/.test(s)) {
        const target = resolvePath(importer, s);
        if (fileExists(target)) return target;
        if (fileExists(target + '.js')) return target + '.js';
        if (fileExists(join(target, 'index.js'))) return join(target, 'index.js');
        return null;
    }
    return resolvePackage(s, dirname(importer));
}

function bundleAssetRoots(assetBase) {
    const base = norm(assetBase);
    const roots = [];
    for (const dir of ASSET_DIRS) {
        const candidate = join(base, dir);
        if (fileExists(candidate)) roots.push(norm(candidate));
    }
    return roots;
}

function collectBundle(entryPath, assetBase) {
    const files = new Set();
    const modules = new Map();
    const jsFiles = new Set();
    const scanned = new Set();
    const queue = [entryPath];
    const roots = bundleAssetRoots(assetBase);

    for (const root of roots) {
        for (const path of listFiles(root)) {
            if (ASSET_EXT.test(path)) addFile(path);
        }
    }

    function addFile(path) {
        const p = norm(path);
        if (p && fileExists(p)) files.add(p);
    }

    addFile(entryPath);
    while (queue.length) {
        const current = queue.shift();
        if (scanned.has(current)) continue;
        scanned.add(current);
        let source;
        try {
            source = readText(current);
        } catch (e) {
            continue;
        }
        for (const spec of specifiers(source)) {
            const resolved = resolveSpecifier(spec, current);
            if (!resolved) continue;
            const target = norm(resolved);
            if (NATIVE_EXT.test(target)) {
                addFile(target);
                continue;
            }
            const isBare = !spec.startsWith('.') && !spec.startsWith('/') &&
                !/^[A-Za-z]:[\\/]/.test(spec);
            const packageRoot = isBare ? findPackageRoot(target) : null;
            addFile(target);
            if (packageRoot) addFile(join(packageRoot, 'package.json'));
            if (isBare && JS_EXT.test(target) && !modules.has(spec))
                modules.set(spec, target);
            if (JS_EXT.test(target)) jsFiles.add(target);
            if (JS_EXT.test(target) && !scanned.has(target)) queue.push(target);
        }
    }
    return { files: [...files], assetRoots: roots, jsFiles: [...jsFiles],
             modules: [...modules].map(([spec, path]) => ({ spec, path })) };
}

function writeBytes(path, bytes) {
    const fd = os.open(String(path), os.O_WRONLY | os.O_CREAT | os.O_TRUNC);
    if (fd < 0) throw new Error('mochijsnative.build: cannot open ' + path);
    let offset = 0;
    while (offset < bytes.length) {
        const n = os.write(fd, bytes.buffer, offset, Math.min(65536, bytes.length - offset));
        if (!n || n < 0) break;
        offset += n;
    }
    os.close(fd);
    return offset;
}

function mainBytecodeFromC(cFile) {
    const source = readText(cFile);
    const calls = source.match(/mbjs_std_eval_binary\(ctx,\s*([A-Za-z0-9_]+),/g) || [];
    const last = calls.length ? calls[calls.length - 1].match(/,\s*([A-Za-z0-9_]+),/) : null;
    const cname = last ? last[1] : null;
    if (!cname) throw new Error('mochijsnative.build: no bytecode array in ' + cFile);
    const match = source.match(new RegExp('const uint8_t ' + cname + '\\[(\\d+)\\] = \\{([\\s\\S]*?)\\};'));
    if (!match) throw new Error('mochijsnative.build: cannot read ' + cname);
    const hex = match[2].match(/0x[0-9a-fA-F]{2}/g) || [];
    const bytes = new Uint8Array(hex.length);
    for (let i = 0; i < hex.length; i++) bytes[i] = parseInt(hex[i].slice(2), 16);
    return bytes;
}

function compileBundledModules(collected, root, entryPath, workDir, name, compiler, moduleFlag) {
    const keyByPath = new Map();
    for (const path of collected.jsFiles) keyByPath.set(norm(path), relativeTo(path, root));

    function rewriteSpecifiers(source, importer) {
        return String(source).replace(/(['"])([^'"\\]+)\1/g, (whole, quote, spec) => {
            if (spec.startsWith('mbjs:') || spec.startsWith('mochibundle:') ||
                NATIVE_EXT.test(spec) || /\s/.test(spec)) return whole;
            const resolved = resolveSpecifier(spec, importer);
            if (!resolved) return whole;
            const key = keyByPath.get(norm(resolved));
            return key ? quote + 'mochibundle:' + key + quote : whole;
        });
    }

    const out = [];
    const aliases = new Map();
    let index = 0;
    for (const path of collected.jsFiles) {
        const abs = norm(path);
        if (abs === norm(entryPath)) continue;
        const key = keyByPath.get(abs);
        const moduleName = 'mochibundle:' + key;
        const sourcePath = join(workDir, name + '_src' + index + '.js');
        const cTarget = join(workDir, name + '_mod' + index + '.c');
        const target = join(workDir, name + '_mod' + index + '.mbc');
        writeText(sourcePath, rewriteSpecifiers(readText(abs), abs));
        exec('cd /d ' + q(workDir) + ' && ' + q(compiler) + ' -e ' + moduleFlag +
             ' -n ' + q(moduleName) + ' -o ' + q(cTarget) + ' ' + q(sourcePath.split('/').pop()));
        writeBytes(target, mainBytecodeFromC(cTarget));
        out.push({ spec: key, name: moduleName, file: target });
        if (!aliases.has(key)) aliases.set(key, moduleName);
        index++;
    }
    for (const item of collected.modules) {
        const key = keyByPath.get(norm(item.path));
        if (key && !aliases.has(item.spec)) aliases.set(item.spec, 'mochibundle:' + key);
    }
    return { modules: out, aliases: [...aliases].map(([spec, moduleName]) => ({ spec, name: moduleName })) };
}

function commonRoot(paths) {
    let root = dirname(paths[0] || '');
    while (root && root !== '/' && !/^[A-Za-z]:$/.test(root)) {
        const prefix = root.replace(/\/+$/, '') + '/';
        if (paths.every((p) => p.startsWith(prefix))) break;
        root = dirname(root);
    }
    return root.replace(/\/+$/, '');
}

function relativeTo(path, root) {
    const p = norm(path);
    const prefix = root.replace(/\/+$/, '') + '/';
    return p.startsWith(prefix) ? p.slice(prefix.length) : p.replace(/^[A-Za-z]:\//, '');
}

function writeHex(writer, bytes) {
    for (let i = 0; i < bytes.length; i += 16) {
        const chunk = [];
        for (let j = i; j < Math.min(i + 16, bytes.length); j++)
            chunk.push('0x' + bytes[j].toString(16).padStart(2, '0'));
        writer.write('  ' + chunk.join(',') + ',\n');
    }
}

function generateBundleHeader(headerPath, name, files, root, mode, embedded, assetRoots) {
    const writer = openWriter(headerPath);
    try {
        const bundleModules = (embedded && embedded.modules) || [];
        const moduleAliases = (embedded && embedded.aliases) || [];
        const assetPrefixes = (assetRoots || []).map((p) => relativeTo(p, root).replace(/\/+$/, '') + '/');
        const rels = files.map((p) => relativeTo(p, root));
        const data = files.map((p) => readBytes(p));
        const extractAll = 1;
        writer.write('#ifndef MOCHI_BUNDLE_H\n#define MOCHI_BUNDLE_H\n' +
            '#include "mbjs.h"\n' +
            '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <time.h>\n' +
            '#define BUNDLE_EXTRACT_ALL ' + extractAll + '\n' +
            '#define BUNDLE_IS_ASSET(p) (0' +
            assetPrefixes.map((p) => ' || !strncmp((p), ' + q(p) + ', ' + p.length + ')').join('') + ')\n' +
            '#define bundle_eval_checked(ctx, buf, len, mod) do { \\\n' +
            '  mbjs_std_eval_binary((ctx), (buf), (len), (mod)); \\\n' +
            '  if (MBJS_HasException(ctx)) { \\\n' +
            '    fprintf(stderr, "mochibundle: eval failed: %s\\n", #buf); \\\n' +
            '    mbjs_std_dump_error(ctx); \\\n' +
            '  } \\\n' +
            '} while (0)\n\n' +
            '#ifdef _WIN32\n#include <direct.h>\n#include <process.h>\n#define MB_SEP \'\\\\\'\n' +
            '#else\n#include <unistd.h>\n#include <sys/stat.h>\n#define MB_SEP \'/\'\n#endif\n\n' +
            'typedef struct { const char *path; const unsigned char *data; unsigned long size; } MochiBundleFile;\n\n');
        for (let i = 0; i < data.length; i++) {
            writer.write('static const unsigned char bundle_f' + i + '[] = {\n');
            writeHex(writer, data[i]);
            writer.write('};\n\n');
        }
        writer.write('static const MochiBundleFile bundle_files[] = {\n');
        for (let i = 0; i < data.length; i++)
            writer.write('  { ' + q(rels[i]) + ', bundle_f' + i + ', ' + data[i].length + ' },\n');
        writer.write('};\n\n');
        const moduleData = bundleModules.map((m) => readBytes(m.file));
        writer.write('typedef struct { const char *name; const unsigned char *data; unsigned long size; } MochiBundleModule;\n\n');
        for (let i = 0; i < moduleData.length; i++) {
            writer.write('static const unsigned char bundle_mod' + i + '[] = {\n');
            writeHex(writer, moduleData[i]);
            writer.write('};\n\n');
        }
        writer.write('static const MochiBundleModule bundle_modules[] = {\n');
        for (let i = 0; i < moduleData.length; i++)
            writer.write('  { ' + q(bundleModules[i].name) + ', bundle_mod' + i + ', ' + moduleData[i].length + ' },\n');
        writer.write(            '};\n\n' +
            'typedef struct { const char *spec; const char *name; } MochiBundleAlias;\n\n' +
            'static const MochiBundleAlias bundle_aliases[] = {\n');
        for (const alias of moduleAliases)
            writer.write('  { ' + q(alias.spec) + ', ' + q(alias.name) + ' },\n');
        writer.write('};\n\n' +
            'static const char *bundle_module_name(const char *spec)\n{\n' +
            '  size_t i;\n' +
            '  for (i = 0; i < sizeof(bundle_aliases) / sizeof(bundle_aliases[0]); i++)\n' +
            '    if (!strcmp(bundle_aliases[i].spec, spec)) return bundle_aliases[i].name;\n' +
            '  return NULL;\n' +
            '}\n\n' +
            'static MBJSValue bundle_module_resolve(MBJSContext *ctx, MBJSValueConst this_val,\n' +
            '                                       int argc, MBJSValueConst *argv)\n{\n' +
            '  const char *spec; const char *name;\n' +
            '  if (argc < 1) return MBJS_UNDEFINED;\n' +
            '  spec = MBJS_ToCString(ctx, argv[0]);\n' +
            '  if (!spec) return MBJS_UNDEFINED;\n' +
            '  name = bundle_module_name(spec);\n' +
            '  MBJS_FreeCString(ctx, spec);\n' +
            '  return name ? MBJS_NewString(ctx, name) : MBJS_UNDEFINED;\n' +
            '}\n\n' +
            'static MBJSValue bundle_module_exists(MBJSContext *ctx, MBJSValueConst this_val,\n' +
            '                                      int argc, MBJSValueConst *argv)\n{\n' +
            '  const char *spec; size_t i;\n' +
            '  if (argc < 1) return MBJS_FALSE;\n' +
            '  spec = MBJS_ToCString(ctx, argv[0]);\n' +
            '  if (!spec) return MBJS_FALSE;\n' +
            '  for (i = 0; i < sizeof(bundle_modules) / sizeof(bundle_modules[0]); i++) {\n' +
            '    if (!strcmp(bundle_modules[i].name, spec)) {\n' +
            '      MBJS_FreeCString(ctx, spec); return MBJS_TRUE;\n' +
            '    }\n' +
            '  }\n' +
            '  MBJS_FreeCString(ctx, spec);\n' +
            '  return MBJS_FALSE;\n' +
            '}\n\n' +
            'static char bundle_root[2048];\n\n' +
            'static const MochiBundleFile *bundle_find(const char *requested)\n{\n' +
            '  char norm[2048]; size_t i, j = 0;\n' +
            '  for (i = 0; requested[i] && j < sizeof(norm) - 1; i++)\n' +
            '    norm[j++] = (requested[i] == \'\\\\\') ? \'/\' : requested[i];\n' +
            '  norm[j] = 0;\n' +
            '  i = 0;\n' +
            '  while (i + 1 < j && norm[i] == \'.\' && norm[i + 1] == \'/\') i += 2;\n' +
            '  while (i < j && norm[i] == \'/\') i++;\n' +
            '  {\n' +
            '    const char *req = norm + i; size_t req_len = strlen(req), k;\n' +
            '    for (k = 0; k < sizeof(bundle_files) / sizeof(bundle_files[0]); k++) {\n' +
            '      const char *path = bundle_files[k].path;\n' +
            '      size_t path_len = strlen(path);\n' +
            '      if (!strcmp(path, req)) return &bundle_files[k];\n' +
            '      if (path_len > req_len && path[path_len - req_len - 1] == \'/\' &&\n' +
            '          !strcmp(path + path_len - req_len, req)) return &bundle_files[k];\n' +
            '    }\n' +
            '  }\n' +
            '  return NULL;\n' +
            '}\n\n' +
            'static MBJSValue bundle_asset_read(MBJSContext *ctx, MBJSValueConst this_val,\n' +
            '                                   int argc, MBJSValueConst *argv)\n{\n' +
            '  const MochiBundleFile *file;\n' +
            '  const char *requested;\n' +
            '  if (argc < 1) return MBJS_UNDEFINED;\n' +
            '  requested = MBJS_ToCString(ctx, argv[0]);\n' +
            '  if (!requested) return MBJS_EXCEPTION;\n' +
            '  file = bundle_find(requested);\n' +
            '  MBJS_FreeCString(ctx, requested);\n' +
            '  if (!file) return MBJS_UNDEFINED;\n' +
            '  return MBJS_NewStringLen(ctx, (const char *)file->data, (size_t)file->size);\n' +
            '}\n\n' +
            'static MBJSValue bundle_asset_exists(MBJSContext *ctx, MBJSValueConst this_val,\n' +
            '                                     int argc, MBJSValueConst *argv)\n{\n' +
            '  const MochiBundleFile *file;\n' +
            '  const char *requested;\n' +
            '  if (argc < 1) return MBJS_FALSE;\n' +
            '  requested = MBJS_ToCString(ctx, argv[0]);\n' +
            '  if (!requested) return MBJS_FALSE;\n' +
            '  file = bundle_find(requested);\n' +
            '  MBJS_FreeCString(ctx, requested);\n' +
            '  return file ? MBJS_TRUE : MBJS_FALSE;\n' +
            '}\n\n' +
            'static void bundle_mkdirs(const char *path)\n{\n' +
            '  char buf[2048]; size_t i, n = 0;\n' +
            '  for (i = 0; path[i] && n < sizeof(buf) - 1; i++)\n' +
            '    buf[n++] = (path[i] == \'/\' || path[i] == \'\\\\\') ? MB_SEP : path[i];\n' +
            '  buf[n] = 0;\n' +
            '  for (i = 1; buf[i]; i++) {\n' +
            '    if (buf[i] == MB_SEP) { char c = buf[i]; buf[i] = 0; mkdir(buf); buf[i] = c; }\n' +
            '  }\n  mkdir(buf);\n}\n\n' +
            'static const char *bundle_path(const char *rel)\n{\n' +
            '  static char buf[4096];\n' +
            '  snprintf(buf, sizeof(buf), "%s%c%s", bundle_root, MB_SEP, rel);\n' +
            '  return buf;\n}\n\n' +
            'static void bundle_cleanup(void)\n{\n' +
            '  size_t i; int pass;\n' +
            '  for (i = 0; i < sizeof(bundle_files) / sizeof(bundle_files[0]); i++)\n' +
            '    remove(bundle_path(bundle_files[i].path));\n' +
            '  for (pass = 0; pass < 16; pass++)\n' +
            '    for (i = 0; i < sizeof(bundle_files) / sizeof(bundle_files[0]); i++) {\n' +
            '      const char *rel = bundle_files[i].path;\n' +
            '      const char *slash = strrchr(rel, \'/\');\n' +
            '      if (slash) { char dir[2048]; size_t len = (size_t)(slash - rel);\n' +
            '        memcpy(dir, rel, len); dir[len] = 0; rmdir(bundle_path(dir)); }\n' +
            '    }\n}\n\n' +
            'static void bundle_init(void)\n{\n' +
            '  const char *tmp = getenv("TEMP"); size_t i;\n' +
            '  if (!tmp) tmp = getenv("TMPDIR");\n  if (!tmp) tmp = ".";\n' +
            '  snprintf(bundle_root, sizeof(bundle_root), "%s%cmochibundle_%s_%ld",\n' +
            '           tmp, MB_SEP, ' + q(name) + ', (long)getpid());\n' +
            '  bundle_mkdirs(bundle_root);\n' +
            '  for (i = 0; i < sizeof(bundle_files) / sizeof(bundle_files[0]); i++) {\n' +
            '    const char *path = bundle_files[i].path;\n' +
            '    const char *slash;\n' +
            '    const char *full;\n' +
            '    FILE *fp;\n' +
            '    if (BUNDLE_IS_ASSET(path)) continue;\n' +
            '    if (!BUNDLE_EXTRACT_ALL &&\n' +
            '        !strstr(path, ".dll") && !strstr(path, ".so") && !strstr(path, ".dylib") &&\n' +
            '        !strstr(path, ".lbrct")) continue;\n' +
            '    slash = strrchr(path, \'/\');\n' +
            '    if (slash) { char dir[2048]; size_t len = (size_t)(slash - path);\n' +
            '      memcpy(dir, path, len); dir[len] = 0; bundle_mkdirs(bundle_path(dir)); }\n' +
            '    full = bundle_path(path);\n' +
            '    fp = fopen(full, "wb");\n' +
            '    if (fp) { if (bundle_files[i].size)\n' +
            '                fwrite(bundle_files[i].data, 1, bundle_files[i].size, fp);\n' +
            '              fclose(fp); }\n' +
            '    else fprintf(stderr, "mochibundle: cannot write %s\\n", full);\n' +
            '  }\n' +
            '  chdir(bundle_root);\n' +
            '#ifdef _WIN32\n  _putenv_s("MOCHI_BUNDLE_DIR", bundle_root);\n' +
            '#else\n  setenv("MOCHI_BUNDLE_DIR", bundle_root, 1);\n#endif\n' +
            '  atexit(bundle_cleanup);\n}\n\n#endif\n');
    } finally {
        writer.close();
    }
}

function patchGeneratedC(cFile, files, root, headerName) {
    let text = readText(cFile).replace(/\r\n/g, '\n');
    const includeAnchor = text.indexOf('#include <string.h>') >= 0
        ? '#include <string.h>' : '#include "mbjs-libc.h"';
    text = text.replace(includeAnchor, includeAnchor + '\n#include "' + headerName + '"');
    text = text.split('mbjs_std_eval_binary(ctx, ').join('bundle_eval_checked(ctx, ');
    text = text.replace('int main(int argc, char **argv)\n{\n',
                        'int main(int argc, char **argv)\n{\n  bundle_init();\n');
    text = text.replace('  ctx = MBJS_NewCustomContext(rt);\n',
        '  ctx = MBJS_NewCustomContext(rt);\n' +
        '  {\n' +
        '    MBJSValue globals = MBJS_GetGlobalObject(ctx);\n' +
        '    MBJS_SetPropertyStr(ctx, globals, "__MOCHI_ASSET_READ__",\n' +
        '                        MBJS_NewCFunction(ctx, bundle_asset_read, "assetRead", 1));\n' +
        '    MBJS_SetPropertyStr(ctx, globals, "__MOCHI_ASSET_EXISTS__",\n' +
        '                        MBJS_NewCFunction(ctx, bundle_asset_exists, "assetExists", 1));\n' +
        '    MBJS_SetPropertyStr(ctx, globals, "__MOCHI_MODULE_EXISTS__",\n' +
        '                        MBJS_NewCFunction(ctx, bundle_module_exists, "moduleExists", 1));\n' +
        '    MBJS_SetPropertyStr(ctx, globals, "__MOCHI_MODULE_NAME__",\n' +
        '                        MBJS_NewCFunction(ctx, bundle_module_resolve, "moduleName", 1));\n' +
        '    MBJS_FreeValue(ctx, globals);\n' +
        '  }\n');
    text = text.replace('  return ctx;\n}\n\nint main',
        '  {\n' +
        '    size_t k;\n' +
        '    for (k = 0; k < sizeof(bundle_modules) / sizeof(bundle_modules[0]); k++) {\n' +
        '      MBJSValue ex;\n' +
        '      mbjs_std_eval_binary(ctx, bundle_modules[k].data, bundle_modules[k].size, 1);\n' +
        '      ex = MBJS_GetException(ctx);\n' +
        '      if (!MBJS_IsNull(ex)) {\n' +
        '        fprintf(stderr, "mochibundle: embedded module %s failed\\n", bundle_modules[k].name);\n' +
        '        MBJS_FreeValue(ctx, ex);\n' +
        '      }\n' +
        '    }\n' +
        '  }\n' +
        '  return ctx;\n}\n\nint main');
    for (const file of files) {
        const abs = '"' + file + '"';
        const rel = relativeTo(file, root);
        text = text.split(abs).join('bundle_path(' + q(rel) + ')');
    }
    writeText(cFile, text);
}

export function build(options = {}) {
    const mode = String(options.mode || 'jit').toLowerCase();
    if (mode !== 'jit' && mode !== 'aot' && mode !== 'mbc')
        throw new Error('mochijsnative.build: mode must be jit, aot or mbc');

    const projectDir = norm(options.projectDir || cwd());
    const entry = norm(options.entry || 'src/server.js');
    const entryPath = /^([A-Za-z]:)?\//.test(entry) ? entry : join(projectDir, entry);
    const entryDir = dirname(entryPath);
    const name = String(options.name || 'app').replace(/[^A-Za-z0-9_-]/g, '_');
    const workDir = norm(options.workDir || DEFAULT_WORK_DIR).replace(/\/+$/, '');
    const engineRoot = norm(options.engineRoot || DEFAULT_ENGINE_ROOT).replace(/\/+$/, '');
    const compiler = resolveCompiler(options.compiler);
    const bytecode = mode === 'mbc' || options.bytecode === true || options.format === 'mbc';
    const out = norm(options.out || join(workDir, name + '_' + mode + (bytecode ? '.mbc' : '.exe')));
    const cFile = join(workDir, name + '_' + mode + (bytecode ? '_bc' : '') + '.c');
    const bundle = options.bundle === true && !bytecode;
    const moduleFlag = options.module === false ? '-C' : '-m';

    exec('if not exist ' + q(workDir) + ' mkdir ' + q(workDir));

    let bundleInfo = null;
    if (bundle) {
        const collected = collectBundle(entryPath, projectDir);
        const root = commonRoot(collected.files);
        const files = collected.files;
        const header = join(workDir, name + '_bundle.h');
        const embedded = { modules: [], aliases: [] };
        generateBundleHeader(header, name, files, root, mode, embedded, collected.assetRoots);
        bundleInfo = { root, header, files: files.map((p) => relativeTo(p, root)),
                       assetRoots: collected.assetRoots, modules: embedded.modules };
    }

    const flag = bytecode ? '-e' : mode === 'jit' ? '-j' : '-e';
    const incDir = options.incDir || 'E:/bcf/mochiberry';
    const libDir = options.libDir || 'E:/bcf/mochiberry/build_manual';
    const jitEnv = mode === 'jit' && !bytecode
        ? 'set MBJS_JIT_INC=' + incDir + '&&set MBJS_JIT_LIB=' + libDir + '&&'
        : '';
    const compileCmd = 'cd /d ' + q(entryDir) + ' && ' + jitEnv + q(compiler) + ' ' + flag +
        ' ' + moduleFlag + ' -n ' + q(name) +
        ' -o ' + q(cFile) + ' ' + q(entryPath.split('/').pop());
    const compileResult = exec(compileCmd);
    if (bytecode) {
        writeBytes(out, mainBytecodeFromC(cFile));
        return { mode, out, cFile, bytecode: true, command: compileCmd, stdout: compileResult.stdout };
    }
    if (!fileExists(cFile))
        throw new Error('mochijsnative.build: compiler failed\n' + compileCmd + '\n' + compileResult.stdout);

    if (bundle)
        patchGeneratedC(cFile, bundleInfo.files.map((p) => join(bundleInfo.root, p)),
                        bundleInfo.root, name + '_bundle.h');

    const gcc = norm(options.gcc || DEFAULT_GCC);
    const strip = norm(options.strip || DEFAULT_STRIP);
    const extraObjects = bundle ? '' :
        q(join(engineRoot, 'build_manual', 'mbjs-opt.o')) + ' ' +
        q(join(engineRoot, 'build_manual', 'mbjs-llvm.o')) + ' ';
    const archive = bundle
        ? ' -Wl,--whole-archive ' + q(join(engineRoot, 'build_manual', 'libmbjs.a')) +
          ' -Wl,--no-whole-archive'
        : ' ' + q(join(engineRoot, 'build_manual', 'libmbjs.a'));
    const linkCmd = gcc + ' -O2 -I ' + q(engineRoot) + ' -I ' + q(workDir) +
        ' -o ' + q(out) + ' ' + q(cFile) + ' ' + extraObjects + archive +
        ' -lm -lpthread -Wl,--defsym=stat64i32=_stat64i32 -Wl,--export-all-symbols' +
        ' && ' + strip + ' -s ' + q(out);
    const linkResult = exec(linkCmd);
    return {
        mode, out, cFile,
        bundle: bundleInfo && { root: bundleInfo.root, header: bundleInfo.header, files: bundleInfo.files },
        command: compileCmd + '\n' + linkCmd,
        stdout: compileResult.stdout + linkResult.stdout
    };
}

export function main(argv = []) {
    const mode = argv[0] || 'jit';
    const entry = argv[1] || 'src/server.js';
    const out = argv[2] && String(argv[2]).indexOf('--') !== 0 ? argv[2] : null;
    const formatArg = argv.find((a) => String(a).indexOf('--format=') === 0);
    const format = formatArg ? formatArg.slice('--format='.length) : null;
    const bytecode = argv.indexOf('--mbc') >= 0 || format === 'mbc' || mode === 'mbc';
    return build({ mode, entry, out, bundle: argv.indexOf('--bundle') >= 0,
                   bytecode, format });
}

export default { build, main };
